/**
 * MURKA Mission B (webots.md AT-W8 / AT-W9): the studio's port of the agromarca scripted-fleet supervisor
 * (src/io/webots/scripted_fleet.ts + murka_missions.ts) against the reference replay of the REAL Python code
 * (tests/fixtures/webots/mission_b_reference.json.gz, generated by mission_b_reference.py: 92 s at 16 ms, final poses,
 * 0.5 s trace, max per-tick steps, visible wheel fields, plan report).
 * 1. synthetic (always runs): the script port equals the Python script and the playback on a dict world seeded with the
 *    reference seeds reproduces the reference to rounding (port fidelity);
 * 2. MURKA (skipIf): played on the imported orchard_demo.wbt station the items end within 1 cm / 0.01 rad of the
 *    reference, and along the replay no platform / crate / module collides with trunks, fences, base, depot or rocks
 *    (studio collision check on the boundingObject colliders).
 */
import { describe, it, expect, beforeAll } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { ScriptedFleet, FleetWorld, Pose4, playScriptedFleet, defaultMissionBScript, MISSION_B, StationFleetWorld, importWebotsWorld, WebotsBuildResult, shortestAngle } from '../src/io/webots';
import { AssetStore } from '../src/scene/assets';
import { Item, SceneObject } from '../src/core/items/item';
import { MobileRobot } from '../src/mobile/items';
import { itemsCollide } from '../src/core/collision/collision';
import { HAS_MURKA, AGRO, murkaSource } from './webots_helpers';

interface Ref {
  dt: number; t_end: number; seed: Record<string, Pose4>; final: Record<string, Pose4>; max_step_m: Record<string, number>;
  wheel_fields_final: Record<string, number[]>; errors: string[]; trace: Array<{ t: number; poses: Record<string, Pose4> }>;
  plan_report: Array<Record<string, number | string | boolean>>; script: unknown;
}
const REF: Ref = JSON.parse(zlib.gunzipSync(fs.readFileSync(path.resolve(__dirname, 'fixtures/webots/mission_b_reference.json.gz'))).toString('utf8'));
const ENTITIES = Object.keys(REF.final);
const r4 = (v: number) => Math.round(v * 1e4) / 1e4;

/** In-memory world like scripted_fleet.DictWorldAdapter. */
class DictWorld implements FleetWorld {
  poses = new Map<string, Pose4>();
  rotations = new Map<string, number[]>();
  constructor(seed: Record<string, Pose4>) { for (const [k, v] of Object.entries(seed)) this.poses.set(k, [...v] as Pose4); }
  hasNode(n: string) { return this.poses.has(n); }
  getPose(n: string): Pose4 { const p = this.poses.get(n); if (!p) throw new Error(`node '${n}' is not in the world`); return p; }
  setPose(n: string, x: number, y: number, z: number, yaw: number) { this.poses.set(n, [x, y, z, yaw]); }
  setFieldRotation(n: string, f: string, r: number[]) { this.rotations.set(`${n}.${f}`, [...r]); }
}

describe('Mission B scripted fleet (port fidelity, synthetic)', () => {
  it('the TypeScript Mission B script equals the script of garden_supervisor.default_mission_b_script', () => {
    expect(JSON.parse(JSON.stringify(defaultMissionBScript()))).toEqual(REF.script);
    expect(defaultMissionBScript(false).waypoints!.some((w) => w.robot_id === 'UTP-G-01')).toBe(false);
  });

  it('plays the script on the reference seeds exactly like the Python supervisor (final poses, trace, steps, wheels, plan report)', () => {
    const world = new DictWorld(REF.seed);
    const prev = new Map(ENTITIES.map((e) => [e, world.getPose(e)]));
    const maxStep: Record<string, number> = Object.fromEntries(ENTITIES.map((e) => [e, 0]));
    const trace: Ref['trace'] = [];
    let n = 0;
    const res = playScriptedFleet(null as never, defaultMissionBScript(), {
      world, dt: REF.dt, tEnd: REF.t_end, depotModules: MISSION_B.DEPOT_MODULES,
      onTick: (t) => {
        n++;
        for (const e of ENTITIES) { const p = world.getPose(e), q = prev.get(e)!; maxStep[e] = Math.max(maxStep[e], Math.hypot(p[0] - q[0], p[1] - q[1])); prev.set(e, p); }
        if (n % 31 === 0 || t + REF.dt > REF.t_end) trace.push({ t: Math.round(t * 1000) / 1000, poses: Object.fromEntries(ENTITIES.map((e) => [e, world.getPose(e).map(r4) as Pose4])) });
      },
    });
    expect(res.errors).toEqual(REF.errors);
    expect(res.ticks).toBe(5750); // t = n * 0.016 <= 92 (IEEE, same in Python)
    for (const e of ENTITIES) expect(world.getPose(e).map(r4), e).toEqual(REF.final[e]);
    for (const e of ENTITIES) expect(maxStep[e], e).toBeCloseTo(REF.max_step_m[e], 9);
    expect(trace.length).toBe(REF.trace.length);
    trace.forEach((s, i) => { expect(s.t).toBe(REF.trace[i].t); expect(s.poses, `t=${s.t}`).toEqual(REF.trace[i].poses); });
    expect(Object.fromEntries([...world.rotations].map(([k, v]) => [k, v.map(r4)]))).toEqual(REF.wheel_fields_final);
    const rows = res.fleet.planReport(Object.fromEntries(Object.entries(REF.seed)) as Record<string, Pose4>);
    expect(rows.length).toBe(REF.plan_report.length);
    rows.forEach((row, i) => {
      const ref = REF.plan_report[i];
      for (const [k, v] of Object.entries(row)) typeof v === 'number' ? expect(v, `${row.robot_id} ${k}`).toBeCloseTo(ref[k] as number, 9) : expect(v).toBe(ref[k]);
    });
    expect(rows.some((r) => r.rate_limited)).toBe(false); // the script respects the 0.5 rad/s turn limit
  });

  it('window plans: tangent turn-drive-turn with trapezoid profile, reverse drive, rate limiting, interp crab walk', () => {
    const f = ScriptedFleet.fromScript({ yaw_mode: 'tangent', waypoints: [
      { robot_id: 'R', start_s: 0, end_s: 10, target: { x: 4, y: 0, yaw: Math.PI / 2 } },
      { robot_id: 'B', start_s: 0, end_s: 10, target: { x: -4, y: 0 }, drive: 'reverse' },
      { robot_id: 'Q', start_s: 0, end_s: 2, target: { x: 0, y: 4, yaw: Math.PI } },
      { robot_id: 'C', start_s: 0, end_s: 4, target: { x: 2, y: 2, yaw: 1 }, yaw_mode: 'interp' },
    ] });
    const rows = f.planReport({ R: [0, 0, 0, 0], B: [0, 0, 0, 0], Q: [0, 0, 0, 0], C: [0, 0, 0, 0] });
    const R = rows.find((r) => r.robot_id === 'R')!;
    expect([R.kind, R.turn_a_s, R.turn_c_s, R.drive_s]).toEqual(['tangent', 0, 1.5 * (Math.PI / 2) / 0.5, 10 - 1.5 * Math.PI]);
    expect(R.peak_turn_rate).toBeCloseTo(0.5, 12);
    expect(R.peak_speed_mps).toBeCloseTo(4 / ((10 - 1.5 * Math.PI) * 0.75), 12); // ramps = a quarter of the drive phase
    const B = rows.find((r) => r.robot_id === 'B')!;
    expect([B.turn_a_s, B.turn_c_s]).toEqual([0, 0]); // backing out: heading stays, no turn
    const Q = rows.find((r) => r.robot_id === 'Q')!;
    expect(Q.rate_limited).toBe(true);
    expect(Q.turn_a_s + Q.turn_c_s).toBeCloseTo(2 * 0.6, 12); // turns compressed into 60 % of the window
    const w = new DictWorld({ R: [0, 0, 0, 0], B: [0, 0, 0, 0], Q: [0, 0, 0, 0], C: [0, 0, 0, 0] });
    f.tick(w, 2); // interp + linear: half way, yaw interpolated (crab walk)
    expect(w.getPose('C').map((v) => Math.round(v * 1e9) / 1e9)).toEqual([1, 1, 0, 0.5]);
    expect(w.getPose('B')[3]).toBe(0); // reversing keeps the heading
    expect(w.getPose('B')[0]).toBeLessThan(0);
    f.tick(w, 10);
    expect(w.getPose('R').map((v) => Math.round(v * 1e9) / 1e9)).toEqual([4, 0, 0, Math.round((Math.PI / 2) * 1e9) / 1e9]);
    expect(w.getPose('C').map((v) => Math.round(v * 1e9) / 1e9)).toEqual([2, 2, 0, 1]);
    expect(shortestAngle(3 * Math.PI)).toBe(Math.PI);
  });
});

describe.skipIf(!HAS_MURKA)('Mission B on the imported orchard_demo.wbt (AT-W8, AT-W9)', () => {
  let r: WebotsBuildResult;
  let world: StationFleetWorld;
  const AGRO_WS = path.posix.dirname(AGRO).replace(/\/src$/, '');
  beforeAll(() => {
    r = importWebotsWorld('src/murca_webots/worlds/orchard_demo.wbt', murkaSource(AGRO_WS), { assets: new AssetStore() });
    world = new StationFleetWorld(r.station);
    // the depot modules have no boundingObject (they never collide in Webots); like the MURKA mission validator, check
    // them with their visual boxes: an undefined collider list makes the collision module use the geometry
    for (const m of MISSION_B.DEPOT_MODULES) { const it = world.item(m) as SceneObject; if (!(it.colliders ?? []).length && it.geometry.length) (it as { colliders?: unknown }).colliders = undefined; }
  }, 180000);

  it('the scenario nodes resolve by name / DEF and start at the reference seeds (1 mm, 1 mrad)', () => {
    for (const [n, s] of Object.entries(REF.seed)) {
      const p = world.getPose(n);
      for (let k = 0; k < 3; k++) expect(Math.abs(p[k] - s[k]), `${n}[${k}]`).toBeLessThan(1e-3);
      expect(Math.abs(shortestAngle(p[3] - s[3])), n).toBeLessThan(1e-3);
    }
    expect(world.item('UTP-G-01')).toBeInstanceOf(MobileRobot);
  });

  it('92 s at 16 ms: final poses within 1 cm / 0.01 rad, 0.5 s trace within 2 cm, no teleports; no collision with trunks, fences, base, depot or rocks', () => {
    const moving = ENTITIES.map((e) => world.item(e)!);
    const movingIds = new Set(moving.flatMap((m) => [...m.walk()].map((i) => i.id)));
    // static obstacles: every top-level object with colliders that the script does not move (the ground excluded)
    const obstacles = r.station.children.filter((c) => !movingIds.has(c.id) && !c.params.ground && [...c.walk()].some((i) => ((i as SceneObject).colliders ?? []).length > 0));
    const names = obstacles.map((o) => o.name);
    for (const kind of [/tree/i, /fence/i, /base/i, /depot/i, /rock/i]) expect(names.some((n) => kind.test(n)), `${kind} in ${names.join(" ")}`).toBe(true);
    const hits = new Set<string>();
    const prev = new Map(ENTITIES.map((e) => [e, world.getPose(e)]));
    const maxStep: Record<string, number> = Object.fromEntries(ENTITIES.map((e) => [e, 0]));
    const traceAt = new Map(REF.trace.map((s) => [s.t, s.poses]));
    let traceErr = 0, n = 0;
    const res = playScriptedFleet(r.station, defaultMissionBScript(), {
      world, dt: REF.dt, tEnd: REF.t_end, depotModules: MISSION_B.DEPOT_MODULES,
      onTick: (t) => {
        n++;
        for (const e of ENTITIES) { const p = world.getPose(e), q = prev.get(e)!; maxStep[e] = Math.max(maxStep[e], Math.hypot(p[0] - q[0], p[1] - q[1])); prev.set(e, p); }
        const ref = traceAt.get(Math.round(t * 1000) / 1000);
        if (ref && n % 31 === 0) for (const e of ENTITIES) { const p = world.getPose(e); traceErr = Math.max(traceErr, Math.hypot(p[0] - ref[e][0], p[1] - ref[e][1], p[2] - ref[e][2])); }
        if (n % 16 === 0) for (const m of moving) for (const o of obstacles) for (const h of itemsCollide(m, o)) hits.add(`t=${t.toFixed(2)} ${h.a.item.name}/${h.a.part} x ${h.b.item.name}/${h.b.part} (${h.depth.toFixed(1)} mm)`);
      },
    });
    expect(res.errors).toEqual([]);
    for (const e of ENTITIES) {
      const p = world.getPose(e), f = REF.final[e];
      expect(Math.hypot(p[0] - f[0], p[1] - f[1], p[2] - f[2]), e).toBeLessThan(0.01);
      expect(Math.abs(shortestAngle(p[3] - f[3])), e).toBeLessThan(0.01);
    }
    expect(traceErr).toBeLessThan(0.02);
    // per-tick steps <= 2.4 cm except the documented hand-overs (scout mast onto UTP-G-02 at t = 0, sprayer arc flight)
    for (const e of ENTITIES.filter((x) => x !== 'module_scout_mast' && x !== 'module_sprayer')) expect(maxStep[e], e).toBeLessThanOrEqual(0.024 + 1e-9);
    expect(maxStep.module_sprayer).toBeLessThan(0.05);
    // the reconfiguration happened: the sprayer rides on UTP-G-02's rear deck pad, the mast is back on its shelf
    const g2 = world.getPose('UTP-G-02'), sp = world.getPose('module_sprayer');
    expect(Math.hypot(sp[0] - (g2[0] - 0.95 * Math.cos(g2[3])), sp[1] - (g2[1] - 0.95 * Math.sin(g2[3])))).toBeLessThan(1e-6);
    expect(world.getPose('module_scout_mast').map(r4)).toEqual(REF.seed.module_scout_mast);
    expect([...hits]).toEqual([]);
  }, 240000);

  it('the collision check is not vacuous: a platform parked on a trunk, a crate in a fence and a module in a rock collide', () => {
    const tree = r.station.find('apple_tree_s1_01')!, fence = r.station.find('fence_north')!, rock = r.station.find('rock_1')!;
    const tp = tree.poseAbs(), fp = fence.poseAbs(), rp = rock.poseAbs();
    world.setPose('UTP-G-03', tp[12] / 1000, tp[13] / 1000, 0.084, 1.5708);
    world.setPose('crate_empty_1', fp[12] / 1000, fp[13] / 1000, 0, 0);
    world.setPose('module_harvester_arm', rp[12] / 1000, rp[13] / 1000, rp[14] / 1000, 0);
    expect(itemsCollide(world.item('UTP-G-03')!, tree).length).toBeGreaterThan(0);
    expect(itemsCollide(world.item('crate_empty_1')!, fence).length).toBeGreaterThan(0);
    expect(itemsCollide(world.item('module_harvester_arm')!, rock).length).toBeGreaterThan(0);
  });
});
